CREATE TABLE IF NOT EXISTS content_documents (id VARCHAR(100) PRIMARY KEY, draft_payload JSONB NOT NULL, published_payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS document_audit (id VARCHAR(36) PRIMARY KEY, document_id VARCHAR(100) NOT NULL, at TIMESTAMPTZ NOT NULL, actor_role VARCHAR(20) NOT NULL, action VARCHAR(80) NOT NULL, block_id VARCHAR(100), detail VARCHAR(500) NOT NULL);
